export default JSON.parse("{\"workId\":\"liezi\",\"chapter\":{\"id\":\"liezi_ch-5\",\"workId\":\"liezi\",\"order\":5,\"title\":\"湯問\",\"difficulty\":2,\"estimatedMinutes\":48,\"passageIds\":[\"liezi_ch-5_p-1\",\"liezi_ch-5_p-2\",\"liezi_ch-5_p-3\",\"liezi_ch-5_p-4\",\"liezi_ch-5_p-5\",\"liezi_ch-5_p-6\",\"liezi_ch-5_p-7\",\"liezi_ch-5_p-8\",\"liezi_ch-5_p-9\",\"liezi_ch-5_p-10\",\"liezi_ch-5_p-11\",\"liezi_ch-5_p-12\",\"liezi_ch-5_p-13\",\"liezi_ch-5_p-14\",\"liezi_ch-5_p-15\",\"liezi_ch-5_p-16\",\"liezi_ch-5_p-17\"],\"tags\":[]},\"passages\":[{\"id\":\"liezi_ch-5_p-1\",\"chapterId\":\"liezi_ch-5\",\"order\":1,\"canonicalText\":\"殷湯問於夏革曰：「古初有物乎？」夏革曰：「古初無物，今惡得物？後之人將謂今之無物，可乎？」殷湯曰：「然則物無先後乎？」夏革曰：「物之始終，初無極已。始或為終，終或為始，惡知其紀？若夫物外之物，事外之事，吾所不識也。」殷湯曰：「上下八方有極盡窮乎？」革曰：「不知也。」湯固問。革曰：「無則無極，有則有盡，吾何以知之？然無極之外，復無極也；無窮之中，復無窮也。朕以是知其無極無窮也，而不知其有極有窮也。」\",\"sentenceIds\":[\"liezi_ch-5_p-1_s-1\",\"liezi_ch-5_p-1_s-2\",\"liezi_ch-5_p-1_s-3\",\"liezi_ch-5_p-1_s-4\",\"liezi_ch-5_p-1_s-5\",\"liezi_ch-5_p-1_s-6\",\"liezi_ch-5_p-1_s-7\",\"liezi_ch-5_p-1_s-8\",\"liezi_ch-5_p-1_s-9\",\"liezi_ch-5_p-1_s-10\",\"liezi_ch-5_p-1_s-11\",\"liezi_ch-5_p-1_s-12\",\"liezi_ch-5_p-1_s-13\",\"liezi_ch-5_p-1_s-14\",\"liezi_ch-5_p-1_s-15\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"商湯向夏朝遺臣夏革請教道：在宇宙極其古遠的最初階段，存在過物質事物嗎？夏革回答說：如果宇宙古遠最初一無所有，那麼今天的萬事萬物又是從何處產生的呢？如果按照這種邏輯，未來的後代人如果妄言今天的世界根本沒有任何物質存在，難道可以嗎？商湯又問：既然如此，那麼萬物的生成演化難道就沒有先後的次序嗎？夏革說：萬物的開端起源與終結歸宿，原本就沒有絕對孤立的界限與終點。這一個週期的終結或許正是下一個週期的開端，下一個週期的開端或許正是上一個週期的終點，誰又能劃定絕對僵化的死板紀元呢？至於那宇宙時空物質世界之外的玄妙世界、客觀萬事之外的超驗事物，那就不是我有限人類認知所能識得的了。商湯又追問道：宇宙上下八方在空間維度上有沒有極限與窮盡呢？夏革回答說：我不知道啊。商湯執意堅持追問。夏革回答說：如果宇宙是純粹的虛無，那自然就沒有任何極限邊界；如果宇宙是由實體物質構成的，那麼具體物質形態自然會有其空間邊界，我又憑什麼去妄加斷言呢？然而在所謂無極的邊界之外，依然是無窮無盡的廣袤空間；在所謂無窮的時空之中，依然包含著無窮無盡的微觀演化。我正是以此推知宇宙時空在本質上是無極無窮的，而根本無法證明它是有極限有窮盡的啊！\",\"analysis\":\"【篇旨與湯問開篇宇宙時空無限論夏革對商湯】〈湯問〉開宗明義——商湯與夏革探討宇宙物質起源、演化循環與空間邊界，提出「物質守恆、始終相銜、時空無極無窮」的宏偉宇宙哲學。\\\\n【詞義訓詁】「古初無物今惡得物」：精彩的物質不滅與客觀存在論；「始或為終終或為始」：宇宙演化的週期循環律；「無極之外復無極」：空間維度的無限開放性。\\\\n【科學哲學意義】早在兩千多年前便確立了宇宙在時間與空間上的無限性，展現出驚人的東方唯物主義時空思辨。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-2\",\"chapterId\":\"liezi_ch-5\",\"order\":2,\"canonicalText\":\"湯又問曰：「四海之外奚有？」革曰：「猶齊州也。」湯曰：「奚以知之？」革曰：「朕南中九疑，北抵幽陵，東逾扶桑，西至弱水。見其凡物，無以異於齊州者。是故以大觀小，以小觀大，知其皆齊也。」\",\"sentenceIds\":[\"liezi_ch-5_p-2_s-1\",\"liezi_ch-5_p-2_s-2\",\"liezi_ch-5_p-2_s-3\",\"liezi_ch-5_p-2_s-4\",\"liezi_ch-5_p-2_s-5\",\"liezi_ch-5_p-2_s-6\",\"liezi_ch-5_p-2_s-7\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"商湯又詢問道：在四海大洋之外的遙遠世界，究竟存在些什麼呢？夏革回答說：那裡的世界與我們中原九州（齊州）完全一樣啊。商湯問：您憑藉什麼知道這一點呢？夏革回答說：我向南親歷過九嶷山，向北抵達過幽陵極地，向東遠眺過扶桑日出之海，向西跋涉到了弱水流沙之境。在那裡所見到的一切自然萬物、山川草木與人類社會，與我們中原九州並沒有本質上的巨大差異。所以從宏觀大尺度去觀察微觀小世界，從小世界推知宏觀大世界，就能深刻懂得整個地球天下的規律本質上都是齊同均一的啊！\",\"analysis\":\"【篇旨與四海之外猶齊州大宇宙全息均質論】夏革論證四海之外與中原大地在物質構成與生態規律上的普遍一致性，提出「以大觀小、以小觀大、知其皆齊」的全息同構認識論。\\\\n【詞義訓詁】「齊州」：齊，中正；指中原神州大地；「九疑幽陵扶桑弱水」：先秦地理東南西北四極坐標；「知其皆齊」：物理法則與自然生態之普適性。\\\\n【地理學與認識論】打破狹隘的地域中心主義與文化優越感，確立普遍平等的地球整體觀與歸納推演邏輯。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-3\",\"chapterId\":\"liezi_ch-5\",\"order\":3,\"canonicalText\":\"太行、王屋二山，方七百里，高萬仞，本在冀州之南，河陽之北。北山愚公者，年且九十，面山而居。懲山北之塞，出入之迂也，聚室而謀曰：「吾與汝畢力平險，指通豫南，達於漢陰，可乎？」雜然相許。其妻獻疑曰：「以君之力，曾不能損魁父之丘，如太行、王屋何？且焉置土石？」雜曰：「投諸渤海之尾，隱土之北。」遂率子孫荷擔者三夫，叩石墾壤，箕畚運於渤海之尾。鄰人京城氏之孀妻有遺男，始齔，跳往助之。寒暑易節，始一反焉。河曲智叟笑而止之曰：「甚矣，汝之不惠！以殘年餘力，曾不能毀山之一毛，其如土石何？」北山愚公長息曰：「汝心之固，固不可徹，曾不若孀妻弱子。雖我之死，有子存焉；子又生孫，孫又生子；子又有子，子又有孫；子子孫孫無窮匱也，而山不加增，何苦而不平？」河曲智叟亡以應。操蛇之神聞之，懼其不已也，告之於帝。帝感其誠，命誇娥氏二子負二山，一厝朔東，一厝雍南。自此，冀之南，漢之陰，無隴斷焉。\",\"sentenceIds\":[\"liezi_ch-5_p-3_s-1\",\"liezi_ch-5_p-3_s-2\",\"liezi_ch-5_p-3_s-3\",\"liezi_ch-5_p-3_s-4\",\"liezi_ch-5_p-3_s-5\",\"liezi_ch-5_p-3_s-6\",\"liezi_ch-5_p-3_s-7\",\"liezi_ch-5_p-3_s-8\",\"liezi_ch-5_p-3_s-9\",\"liezi_ch-5_p-3_s-10\",\"liezi_ch-5_p-3_s-11\",\"liezi_ch-5_p-3_s-12\",\"liezi_ch-5_p-3_s-13\",\"liezi_ch-5_p-3_s-14\",\"liezi_ch-5_p-3_s-15\",\"liezi_ch-5_p-3_s-16\",\"liezi_ch-5_p-3_s-17\",\"liezi_ch-5_p-3_s-18\",\"liezi_ch-5_p-3_s-19\",\"liezi_ch-5_p-3_s-20\",\"liezi_ch-5_p-3_s-21\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"太行山與王屋山兩座巍峨巨山，方圓綿延七百里，高達幾萬仞，原本坐落在冀州的南部、河陽的北面。北山住著一位名叫愚公的老人，年紀將近九十歲了，正對著這兩座大山居住。他深受這兩座大山阻隔北面道路交通、出入通行必須繞道極其迂迴遙遠的苦楚，於是召集全家老小共同商議說：我打算同你們一起竭盡全力剷平這兩座險峻大山，開闢出一條一直通向豫州南部、直達漢水南岸的康莊大道，你們看行不行？大家紛紛雜然表示贊同。愚公的妻子提出心中的疑慮說：憑藉您這把年紀與體力，連魁父那樣的小土丘都無法削平削去，又能把太行、王屋這兩座大山怎麼樣呢？更何況挖出來的那麼多泥土石塊又將安放在哪裡呢？眾人七嘴八舌回答說：全部傾倒運送到渤海的邊緣、隱土國的北面去！愚公於是率領能夠挑擔出力的子孫三個人，鑿擊岩石、挖掘泥土，用簸箕竹筐將土石運送到渤海的邊緣。鄰居京城氏寡婦家有一個剛剛換乳牙的小男孩（始齔），也歡蹦亂跳地跑來熱情相助。冬去春來寒暑季節交替更迭，往返運送土石一趟才僅僅能回到家一次！黃河彎道處的智叟看見後嘲笑著阻攔愚公說：你也太愚蠢、太缺乏智慧了！憑藉你這垂暮之年的殘存殘力，連山上的一根草木毛髮都無法毀損削去，又能把那漫山遍野的土石怎麼樣呢？北山愚公長長嘆了一口氣說：你的思想觀念真是頑固到了極點，頑固得簡直冥頑不化不可救藥，連寡婦家的小小孩童都比不上！縱然我有一天會死掉，但我還有兒子活在世上；兒子又會生孫子，孫子又會生兒子；兒子又有兒子，孫子又有孫子；子子孫孫代代繁衍是無窮無盡的啊！而這大山卻永遠不會再增高長大，又何愁不能把它徹底剷平呢！河曲智叟被駁斥得啞口無言無言以對。山中掌管山川神靈的操蛇之神聽聞了這番豪言壯語，深深害怕愚公家族這樣世世代代挖山挖個不停，急忙向天帝報告了這件事。天帝被愚公堅韌不拔的至誠精神所深深感動，命令大力神誇娥氏的兩個神力兒子揹走了這兩座大山，一座放置在朔方以東，一座放置在雍州以南。自此之後，冀州的南部直到漢水的南岸，再也沒有任何高山大嶺阻隔阻斷交通了！\",\"analysis\":\"【篇旨與愚公移山人定勝天持之以恆民族精神史詩】中華民族最偉大的實踐意志與生態改造寓言——九十歲愚公面對太行王屋，以「子子孫孫無窮匱、而山不加增」的無限代際複利思維，戰勝目光短淺之智叟，展現震撼天地的堅韌奮鬥精神。\\\\n【詞義訓詁】「出入之迂」：交通阻隔閉塞；「始齔」：齔，音趁，七八歲換乳牙之時；「子子孫孫無窮匱」：代際長期主義與堅定信仰；「命誇娥氏二子負山」：以浪漫主義神話獎賞人類改造世界的偉大意志。\\\\n【民族精神圖騰】「愚公移山」成為中華民族不畏艱險、自強不息、迎難而上的最高精神象徵與實幹哲學。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-4\",\"chapterId\":\"liezi_ch-5\",\"order\":4,\"canonicalText\":\"夸父不量力，欲追日影，逐之於隅谷之際。渴欲得飲，赴飲河、渭。河、渭不足，將走北飲大澤。未至，道渴而死。棄其杖，屍膏肉所浸，生鄧林。鄧林彌廣數千里焉。\",\"sentenceIds\":[\"liezi_ch-5_p-4_s-1\",\"liezi_ch-5_p-4_s-2\",\"liezi_ch-5_p-4_s-3\",\"liezi_ch-5_p-4_s-4\",\"liezi_ch-5_p-4_s-5\",\"liezi_ch-5_p-4_s-6\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"誇父不自量力，企圖追趕太陽奔馳的光影，一路追逐到了太陽落山的隅谷邊緣。追得口乾舌燥極度渴望喝水，於是飛奔撲向黃河與渭水痛飲。黃河與渭水的滔滔江水都被他喝乾了依然不足以解渴，他又準備向北奔跑去痛飲北方的大澤浩瀚之水。然而尚未抵達大澤，就在半路上因極度乾渴而悲壯倒地死去。他死時拋棄丟下的那根手杖，在軀體脂膏血肉的滋潤浸潤之下，化生繁衍出了一片廣袤繁茂的桃林（鄧林）。這片鄧林桃林向外蔓延生長，方圓廣達數千里之遙！\",\"analysis\":\"【篇旨與夸父逐日鄧林彌廣探索自然英雄史詩】上古神話最波瀾壯闊的探索悲歌——夸父逐日渴死中途，手杖化為數千里廣大鄧林，展現人類祖先挑戰自然極限、死而不已澤被後世的悲壯探索精神。\\\\n【詞義訓詁】「隅谷」：古代神話中日落之處；「道渴而死」：為理想追求殉道；「棄杖生鄧林」：鄧林，桃林；生命消逝轉化為豐沛的生態遺產。\\\\n【英雄主義哲學】將看似失敗的個體殉道轉化為孕育文明綠洲的永恆豐碑，象徵人類對光明與真理永不停歇的壯烈求索。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-5\",\"chapterId\":\"liezi_ch-5\",\"order\":5,\"canonicalText\":\"伯牙善鼓琴，鍾子期善聽。伯牙鼓琴，志在高山。鍾子期曰：「善哉！峨峨兮若泰山！」志在流水。鍾子期曰：「善哉！洋洋兮若江河！」伯牙所念，鍾子期必得之。伯牙遊於泰山之陰，卒逢暴雨，止於巖下；心悲，乃援琴而鼓之。初為霖雨之操，更造崩山之音。曲每奏，鍾子期輒窮其趣。伯牙乃舍琴而歎曰：「善哉，善哉！子之聽夫！志想像猶吾心也。吾於何逃聲哉？」子期死，伯牙謂世再無知音，乃破琴絕絃，終身不復鼓。\",\"sentenceIds\":[\"liezi_ch-5_p-5_s-1\",\"liezi_ch-5_p-5_s-2\",\"liezi_ch-5_p-5_s-3\",\"liezi_ch-5_p-5_s-4\",\"liezi_ch-5_p-5_s-5\",\"liezi_ch-5_p-5_s-6\",\"liezi_ch-5_p-5_s-7\",\"liezi_ch-5_p-5_s-8\",\"liezi_ch-5_p-5_s-9\",\"liezi_ch-5_p-5_s-10\",\"liezi_ch-5_p-5_s-11\",\"liezi_ch-5_p-5_s-12\",\"liezi_ch-5_p-5_s-13\",\"liezi_ch-5_p-5_s-14\",\"liezi_ch-5_p-5_s-15\",\"liezi_ch-5_p-5_s-16\",\"liezi_ch-5_p-5_s-17\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"俞伯牙極其擅長彈奏古琴，鍾子期極其擅長精妙聆聽。伯牙撫弄古琴琴絃，內心思緒寄託在巍峨高山之上，鍾子期讚嘆道：彈得太美妙了！巍峨高聳啊就如同巍巍泰山一樣挺拔！伯牙心中思緒寄託在奔騰流水之上，鍾子期讚嘆道：彈得太美妙了！浩瀚澎湃啊就如同奔騰江河一樣壯闊！伯牙心中所思所念的任何意象，鍾子期必定能精準捕捉心領神會。有一次伯牙漫步遊歷在泰山的北面，突然遭遇了一場狂暴暴雨，被迫躲避停留在山岩懸崖之下；內心湧起無盡悲涼感慨，於是拿出古琴彈奏起來。起初彈奏出連綿陰雨淒涼的《霖雨操》，隨後又創作彈奏出驚天動地的大山崩塌之音（崩山之音）。每彈奏出一首新曲調，鍾子期都能徹底窮盡理解其中的深奧意趣。伯牙於是放下古琴長嘆一聲說：太好了，太好了！您的這對神耳啊！您所聽出的精神意境與我的內心完全融為一體，我的心聲在您面前哪裡還能有絲毫隱藏躲避呢！後來鍾子期不幸患病去世，伯牙悲痛欲絕認定全天下再也沒有任何人能成為自己的真正知音了，於是毅然摔碎古琴扯斷琴絃（破琴絕絃），一輩子再也不曾彈奏過古琴！\",\"analysis\":\"【篇旨與伯牙絕絃高山流水高山仰止千古知音絕唱】中國藝術哲學與心靈美學至高典範——伯牙撫琴高山流水，鍾子期窮其雅趣；子期死伯牙破琴絕絃，確立「高山流水遇知音」的中華知音美學文化圖騰。\\\\n【詞義訓詁】「峨峨兮若泰山」：峨峨，高聳貌；「洋洋兮若江河」：洋洋，浩瀚廣大貌；「破琴絕絃」：知音已逝，藝術生命與情感寄託的終極純潔與決絕。\\\\n【心靈感應美學】藝術的最高境界是靈魂深處的無礙共鳴，超越技術形式達到「志想像猶吾心」的心靈融通。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-6\",\"chapterId\":\"liezi_ch-5\",\"order\":6,\"canonicalText\":\"孔子東遊，見兩小兒辯鬥，問其故。一兒曰：「我以日始出時去人近，而日中時遠也。」一兒以日初出遠，而日中時近也。一兒曰：「日初出大如車蓋，及日中則如盤盂，此不為遠者小而近者大乎？」一兒曰：「日初出滄滄涼涼，及其日中如探湯，此不為近者熱而遠者涼乎？」孔子不能決也。兩小兒笑曰：「孰為汝多知乎？」\",\"sentenceIds\":[\"liezi_ch-5_p-6_s-1\",\"liezi_ch-5_p-6_s-2\",\"liezi_ch-5_p-6_s-3\",\"liezi_ch-5_p-6_s-4\",\"liezi_ch-5_p-6_s-5\",\"liezi_ch-5_p-6_s-6\",\"liezi_ch-5_p-6_s-7\",\"liezi_ch-5_p-6_s-8\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孔子向東方遊學遊歷，看見兩個天真爛漫的小孩正在面紅耳赤地激烈爭辯，便走上前詢問他們爭辯的緣由。一個小孩說：我認為太陽剛升起來的時候距離我們人最近，而到了正午時分距離我們最遠。另一個小孩則認為太陽剛升起時距離最遠，而到了正午時分距離最近。第一個小孩反駁說：太陽剛升起來的時候龐大得如同馬車的車蓋，等到到了正午時分卻縮小得如同一個小盤子碗盂，這難道不正是因為距離遙遠的看起來小、距離靠近的看起來大嗎？第二個小孩反駁說：太陽剛升起來的時候氣候清寒冰涼（滄滄涼涼），等到到了正午時分卻酷熱得如同把手伸進了滾燙的熱水之中（如探湯），這難道不正是因為靠近熱源的感到炎熱、距離遙遠的感到涼爽嗎？孔子站在一旁，思索良久也無法給出權威的裁判裁決。兩個小孩拍手大笑著嘲笑說：誰說您老人家是天下無所不知的萬能大智者呢？\",\"analysis\":\"【篇旨與兩小兒辯日視覺與熱覺二律背馳知之為知之】先秦科學觀察與邏輯思辨千古名篇——兩小兒各執視覺大小（視角參照物效應）與熱覺溫度（大氣光照入射角效應）展開爭辯，孔子實事求是「不能決」，展現大思想家「知之為知之、不知為不知」的誠實治學品格。\\\\n【詞義訓詁】「滄滄涼涼」：清涼寒冷；「探湯」：湯，熱水；把手伸進沸水；「孰為汝多知」：以童言無忌解構聖人全知全能之神話。\\\\n【科學啟示】揭示了感官經驗（視覺與觸覺）的局限性與相對性，確立科學真理必須超越直覺經驗、依託光學與天體物理學客觀測量的啟蒙價值。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-7\",\"chapterId\":\"liezi_ch-5\",\"order\":7,\"canonicalText\":\"周穆王西巡狩，越昆侖，不至弇山，反還。中道，塗之人有以巧工謁者，名曰偃師。穆王薦之，問曰：「若何能？」偃師曰：「臣唯命所試。然臣已造一物，願王先觀之。」穆王曰：「日以俱來。」明日，偃師謁見王。王疾迎之曰：「若與偕來者何人邪？」對曰：「臣之所造能倡者。」穆王驚視之，趣步俯仰，信人也。巧夫！頞其頤，則歌合律；捧其手，則舞應節。千變萬化，惟意所適。王以為實人也，與盛姬內御並觀之。技將畢，倡者瞬目而招王之左右侍妾。王大怒，立欲誅偃師。偃師大恐，立剖散倡者以示王，皆傅會革、木、膠、漆、白、黑、丹、青之所為。王諦料之，內則肝、膽、心、肺、脾、腎、腸、胃，外則筋、骨、支、節、皮、毛、齒、髮，皆假物也，而無不畢具者。合之復如初見。王試廢其心，則口不能言；廢其肝，則目不能視；廢其腎，則足不能步。穆王始悅而歎曰：「人之巧，乃可與造化者同功乎！」詔貳車載之以歸。\",\"sentenceIds\":[\"liezi_ch-5_p-7_s-1\",\"liezi_ch-5_p-7_s-2\",\"liezi_ch-5_p-7_s-3\",\"liezi_ch-5_p-7_s-4\",\"liezi_ch-5_p-7_s-5\",\"liezi_ch-5_p-7_s-6\",\"liezi_ch-5_p-7_s-7\",\"liezi_ch-5_p-7_s-8\",\"liezi_ch-5_p-7_s-9\",\"liezi_ch-5_p-7_s-10\",\"liezi_ch-5_p-7_s-11\",\"liezi_ch-5_p-7_s-12\",\"liezi_ch-5_p-7_s-13\",\"liezi_ch-5_p-7_s-14\",\"liezi_ch-5_p-7_s-15\",\"liezi_ch-5_p-7_s-16\",\"liezi_ch-5_p-7_s-17\",\"liezi_ch-5_p-7_s-18\",\"liezi_ch-5_p-7_s-19\",\"liezi_ch-5_p-7_s-20\",\"liezi_ch-5_p-7_s-21\",\"liezi_ch-5_p-7_s-22\",\"liezi_ch-5_p-7_s-23\",\"liezi_ch-5_p-7_s-24\",\"liezi_ch-5_p-7_s-25\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"周穆王向西巡狩出巡，跨越了巍峨崑崙山，尚未抵達極西弇茲山就班師折返。走到半路上，路上有一個身懷絕技的巧手工匠前來求見，他的名字叫做偃師。周穆王召見了他，問道：你有什麼特殊本領呢？偃師回答說：只要大王命令微臣嘗試做的，微臣無不遵命；不過微臣手頭已經製造好了一件器物，希望大王能先行賞玩觀看。穆王說：明天你把它帶過來一同覲見吧。第二天，偃師前來朝見穆王。穆王定睛一看驚奇地問道：同你一起走進來的究竟是什麼人呀？偃師回答說：這正是微臣親手製造製造出來的歌舞藝人（能倡者，即古代仿生機器人）！穆王震驚地仔細打量它，只見它快步快走、俯仰鞠躬，完全是一個活生生的真人啊！真是精巧絕倫啊！輕輕按壓它的下巴，它就能合著五音律呂唱出美妙歌聲；輕輕抬起它的雙手，它就能踩著樂曲節奏跳出曼妙舞蹈。千變萬化，完全隨主人的心意任意操控！穆王完全以為它是個真正的真人，於是特地召來最寵愛的盛姬與三宮後宮嬪妃一同前來觀看。表演即將結束之際，這個歌舞機器人竟然眨動雙眼（瞬目），公然向穆王身邊的左右侍妾秋波傳情報以挑逗！穆王勃然大怒，當場認定這是個假人戲弄王妃，下令立刻斬首誅殺偃師。偃師嚇得魂飛魄散，當場將這個歌舞人偶徹底拆解剖開散落一地給穆王過目：只見它的內部完全是用皮革、木料、膠水、油漆以及白、黑、紅、青等各色彩料拼湊組裝而成的！穆王走上前仔細檢驗審視它，發現其內部結構具備人工仿製的肝、膽、心、肺、脾、腎、腸、胃等五臟六腑，外部則具備人造的筋絡、骨骼、四肢、關節、皮膚、毛髮、牙齒，全部全都是假的人造物料，但人體的一切生理器官竟然無一不齊全完備！重新將零部件拼裝組合起來，立刻又恢復成了剛才栩栩如生的模樣。穆王親自做實驗：試著拆除拿掉它的心臟，它的嘴巴就立刻無法開口說話；試著拆除它的肝臟，它的雙眼就立刻無法看見光芒；試著拆除它的腎臟，它的雙腿就立刻癱瘓無法邁步邁出腳步。穆王這才轉怒為喜，由衷讚嘆驚呼道：人類巧奪天工的科學技術，難道竟然能夠達到與大自然天地造化同等神妙的功力嗎！隨即下令用天子副車（貳車）隆重將偃師與其機械裝置載運回國。\",\"analysis\":\"【篇旨與偃師造倡古代科幻人造人機器人巔峯之作】世界科技文學史上最震撼的人工智能與仿生機器人預言史詩——偃師製造「趣步俯仰、歌舞應節、五臟外肢俱全」的仿生機器人，穆王親自進行模組化器官功能測試（廢心不能言、廢肝不能視、廢腎不能步），發出「人之巧可與造化同功」之浩嘆！\\\\n【詞義訓詁】「能倡者」：倡通唱，能歌善舞之仿生藝人；「皆傅會革木膠漆」：傅會，拼裝黏合；純粹機械材料構成；「王諦料之」：諦，音第，仔細審視；料，檢驗。\\\\n【人工智能與機器人哲學】兩千多年前的中國古人便已精確構想出具備自主動作、模組化生理控制系統與擬人情感表現的機器人，展現出驚人的機械控制論與科技哲學想像力。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-8\",\"chapterId\":\"liezi_ch-5\",\"order\":8,\"canonicalText\":\"魯公扈、趙齊嬰二人有疾，同請扁鵲求治。扁鵲治之。既同愈。謂公扈、齊嬰曰：「汝曩之所疾，自外而入者，故藥石之所已。今有疾，並生於齊，與生偕長，予為汝攻之，何如？」二人曰：「願聞其狀。」扁鵲謂公扈曰：「汝志強而氣弱，故足於謀而寡於斷。齊嬰志弱而氣強，故少於慮而喪於勇。若換汝之心，則均於善矣。」扁鵲遂飲二人毒酒，迷死三日，剖胸探心，易而置之；投以神藥，既悟如初。二人辭歸。於是公扈反齊嬰之室，賂其妻子，妻子弗識。齊嬰反公扈之室，室人亦弗識。二室訟，求審於扁鵲。扁鵲辨其所由，訟乃息。\",\"sentenceIds\":[\"liezi_ch-5_p-8_s-1\",\"liezi_ch-5_p-8_s-2\",\"liezi_ch-5_p-8_s-3\",\"liezi_ch-5_p-8_s-4\",\"liezi_ch-5_p-8_s-5\",\"liezi_ch-5_p-8_s-6\",\"liezi_ch-5_p-8_s-7\",\"liezi_ch-5_p-8_s-8\",\"liezi_ch-5_p-8_s-9\",\"liezi_ch-5_p-8_s-10\",\"liezi_ch-5_p-8_s-11\",\"liezi_ch-5_p-8_s-12\",\"liezi_ch-5_p-8_s-13\",\"liezi_ch-5_p-8_s-14\",\"liezi_ch-5_p-8_s-15\",\"liezi_ch-5_p-8_s-16\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魯國的公扈與趙國的齊嬰兩個人都患了病，一同前往向天下神醫扁鵲求醫救治。扁鵲施展醫術為他們治療，兩人的病情很快一同痊癒了。扁鵲隨後對公扈和齊嬰說：你們過去所患的疾病，是從外部感受風寒邪氣侵入體內的，所以用中藥草石就能輕易治癒。然而你們如今體內還有一種潛在的嚴重先天性人格缺陷（疾），是與生俱來從胎裡帶出來的、伴隨著你們生命一同長大的，我來替你們徹底醫治攻克它，怎麼樣？兩個人驚訝地說：我們很想聽聽具體病狀！扁鵲對公扈說：你心志高遠堅強但性格魄力氣血不足（志強而氣弱），所以你滿腹智謀策略卻極度優柔寡斷缺乏決斷魄力；而齊嬰性格氣魄暴烈但心智思維軟弱（志弱而氣強），所以他行事極度缺乏深思熟慮而往往因盲動匹夫之勇招致慘敗。如果能把你們兩個人的心臟互相對調移植過來（換汝之心），那麼你們兩個人的人格就都能達到剛柔相濟的至善完美境界了！扁鵲於是讓兩個人喝下麻醉藥酒（毒酒），使他們深度昏迷麻醉了整整三天，隨後親自剖開他們的胸膛取出心臟，互相對調置換安裝好；再給他們敷上神妙的生肌止血良藥，兩人甦醒過來後完好如初健康如初。兩人拜謝扁鵲後辭行回家。然而心臟對調之後認知與人格發生了徹底置換：公扈徑直走回了齊嬰的家中，親密地呼喚齊嬰的妻子兒女，齊嬰的妻兒驚恐萬分根本不認識他；而齊嬰則徑直走回了公扈的家中，公扈的家人同樣根本不認識他。兩家為了爭奪丈夫打起官司，告到官府請求扁鵲出庭作證審理。扁鵲當堂辨析解釋了心臟移植導致人格記憶置換的原委由來，這場離奇的世紀官司才徹底平息止歇！\",\"analysis\":\"【篇旨與扁鵲換心器官移植與心靈身心二元論科幻名篇】世界醫學史與科幻文學史上最早的「心臟器官移植與人格身心哲學公案」——扁鵲用麻醉酒（麻沸散萌芽）施行開胸心臟互換手術以平衡「志強氣弱」與「志弱氣強」之性格缺陷，引發社會倫理與身分認同爭端。\\\\n【詞義訓詁】「毒酒迷死三日」：古代全身麻醉技術之神奇構想；「剖胸探心易而置之」：開胸心臟移植術；「志強氣弱 vs 志弱氣強」：心理學神經類型（抑鬱質 vs 膽汁質）之精確診斷。\\\\n【身分認同與生命倫理】深刻探討「自我認知是由大腦/心臟決定，還是由肉體外貌決定」的現代心靈哲學（Mind-Body Problem）核心命題。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-9\",\"chapterId\":\"liezi_ch-5\",\"order\":9,\"canonicalText\":\"甘蠅，古之善射者，彀弓而獸伏鳥下。弟子名飛衛，學射於甘蠅，而巧過其師。紀昌者，又學射於飛衛。飛衛曰：「爾先學不瞬，而後可言射矣。」紀昌歸，偃臥其妻之機下，以目承牽挺。二年之後，雖錐末倒眥，而不瞬也。以告飛衛。飛衛曰：「未也，必學視而後可。視小如大，視微如著，而後告我。」昌以旄牛尾之毛懸蝨於牖，南面而望之。旬日之間，浸大也；三年之後，如車輪焉。以睹餘物，皆丘山也。乃以燕角之弧、朔蓬之簳射之，貫蝨之心，而懸不絕。以告飛衛。飛衛高蹈拊膺曰：「汝得之矣！」紀昌既盡衛之術，計天下之敵己者，一人而已，乃謀殺飛衛。相遇於野，二人交射；中路，矢鋒相觸，墜於地，而塵不揚。飛衛之矢先窮。紀昌遺一矢，既發，飛衛以棘刺之端扞之，而無差焉。於是二子泣而投弓，相與拜於塗，請為父子。\",\"sentenceIds\":[\"liezi_ch-5_p-9_s-1\",\"liezi_ch-5_p-9_s-2\",\"liezi_ch-5_p-9_s-3\",\"liezi_ch-5_p-9_s-4\",\"liezi_ch-5_p-9_s-5\",\"liezi_ch-5_p-9_s-6\",\"liezi_ch-5_p-9_s-7\",\"liezi_ch-5_p-9_s-8\",\"liezi_ch-5_p-9_s-9\",\"liezi_ch-5_p-9_s-10\",\"liezi_ch-5_p-9_s-11\",\"liezi_ch-5_p-9_s-12\",\"liezi_ch-5_p-9_s-13\",\"liezi_ch-5_p-9_s-14\",\"liezi_ch-5_p-9_s-15\",\"liezi_ch-5_p-9_s-16\",\"liezi_ch-5_p-9_s-17\",\"liezi_ch-5_p-9_s-18\",\"liezi_ch-5_p-9_s-19\",\"liezi_ch-5_p-9_s-20\",\"liezi_ch-5_p-9_s-21\",\"liezi_ch-5_p-9_s-22\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"甘蠅是古代著名的神射手，只要他一拉開弓弦，地上的野獸就會嚇得伏地不敢動，天上的飛鳥就會嚇得自行掉落下來。他有一個傑出的弟子名叫飛衛，跟隨甘蠅學習射箭，其高超技藝甚至超越了他的老師。後來又有一個名叫紀昌的人，慕名前來跟隨飛衛學習射箭。飛衛告訴他說：你必須先學會雙眼目不轉睛、永不眨眼（學不瞬），然後纔能有資格同我談論射箭技術！紀昌回到家中，仰面躺在妻子的織布機下面，用雙眼死死盯著織布機上下踏動穿梭的腳踏板挺桿（牽挺）。苦苦練習了整整兩年之後，縱然有人拿著鋒利的錐子尖直接倒刺向他的眼角眼珠，他的眼皮也連眨都不會眨一下了！紀昌興奮地跑去稟告飛衛。飛衛卻平靜地說：這還遠遠不夠呢！你必須進一步學習視覺觀察的本領（學視），練習到看微小的事物如同看龐大巨物一樣清晰，看隱微的細節如同看顯著的物體一樣醒目，然後再來告訴我！紀昌回到家中，用一根犛牛尾巴的細毛拴住一隻極其微小的蟣蝨，懸掛在向陽的南面窗戶上，每天面朝南面凝神死死注視著它。十天半個月下來，眼中的蟣蝨漸漸變大了；苦苦凝視練習了三年之後，眼中的那隻小蟣蝨竟然巨大得如同巨大的馬車車輪一樣龐大無比！再用這種眼睛去看世間其餘萬物，全都如同巍峨丘陵大山一樣巨大！紀昌於是拿著用燕國牛角製作的寶弓、搭上用北方蓬蒿製作的利箭，對準窗前懸掛的蟣蝨一箭射去，利箭精準貫穿射透了那隻微小蟣蝨的心臟，而懸掛著蟣蝨的那根纖細犛牛毛竟然完好無損絲毫未被射斷！紀昌跑去把這個成果告訴了飛衛。飛衛激動得跳起身來拍著胸脯讚嘆驚呼道：你現在終於徹底掌握射箭的神技了！紀昌在徹底學全了飛衛的全部射箭絕技之後，心中暗自盤算全天下能同自己匹敵爭雄的對手只剩下飛衛一人而已，於是動了殺機圖謀刺殺恩師飛衛。兩人在郊外曠野偶遇，各自拔弓搭箭展開殊死對射；在半空之中，兩支利箭的箭鏃尖頭精準正面猛烈撞擊在一起，雙雙垂直墜落在地上，而連地上的塵土都未被震揚起來！飛衛的箭囊中的利箭首先射光了，紀昌手中還殘留著最後一支致命利箭；紀昌搭弓將最後一箭射出，飛衛在千鈞一發之際拔出身邊一根小酸棗荊棘的尖刺，迎著箭頭精準格擋抵擋住了利箭，絲毫沒有任何差錯偏差！在這種神乎其技的較量面前，師徒兩人都感動得熱淚盈眶拋棄了長弓，雙雙跪拜在道路之上，結拜為情同父子的生死至交！\",\"analysis\":\"【篇旨與紀昌學射貫蝨穿心技藝心理學極致典範】世界技能學習與專注力訓練最高名篇——飛衛指導紀昌「學不瞬（意志定力）」與「學視（微觀放大認知力）」，歷經五年苦修達到「貫蝨之心而懸不絕」，展現專注力對神經感官機能的極致重塑。\\\\n【詞義訓詁】「學不瞬」：抑制眨眼反射的神經控制力；「視小如大視微如著」：大腦神經對視覺信號的主動聚焦放大；「貫蝨之心懸不絕」：射箭技藝出神入化之最高意象。\\\\n【工匠精神與心理訓練】揭示一切卓越技能的習得，皆需從最枯燥的底層神經控制與基礎功法入手，打破急功近利方能成就大師。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-10\",\"chapterId\":\"liezi_ch-5\",\"order\":10,\"canonicalText\":\"薛譚學謳於秦青，未窮青之術，自謂盡之，遂辭歸。秦青弗止，餞於郊衢，撫節悲歌，聲振林木，響遏行雲。薛譚乃謝求反，終身不敢言歸。秦青顧謂其友曰：「昔韓娥東之齊，匱糧，過雍門，鬻歌假食。既去，而餘音繞梁，三日不絕，左右以其人弗去。過逆旅，逆旅人辱之。韓娥因曼聲哀哭，一里老幼悲愁，垂涕相對，三日不食。急追而謝之，娥復為曼聲長歌。一里老幼喜躍抃舞，弗能自禁，忘向之悲也。乃厚賂發之。故雍門之人至今善歌哭，放娥之遺聲也。」\",\"sentenceIds\":[\"liezi_ch-5_p-10_s-1\",\"liezi_ch-5_p-10_s-2\",\"liezi_ch-5_p-10_s-3\",\"liezi_ch-5_p-10_s-4\",\"liezi_ch-5_p-10_s-5\",\"liezi_ch-5_p-10_s-6\",\"liezi_ch-5_p-10_s-7\",\"liezi_ch-5_p-10_s-8\",\"liezi_ch-5_p-10_s-9\",\"liezi_ch-5_p-10_s-10\",\"liezi_ch-5_p-10_s-11\",\"liezi_ch-5_p-10_s-12\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"薛譚跟隨大師秦青學習聲樂歌唱（學謳），尚未徹底窮盡融會秦青的全部精深技藝，便自以為自己已經把老師的本領全部學到手了，於是向老師正式提出辭行準備回家。秦青也沒有強行挽留他，在郊外大道（郊衢）上為他設宴餞行；酒席之上，秦青手打節拍引吭高歌悲壯長嘯，那宏亮嘹亮的歌聲震動了整個森林樹木（聲振林木），那穿透雲霄的迴響直接遏制阻擋了天上流動的白雲（響遏行雲）！薛譚聽得目瞪口呆無比震撼，當場跪地痛哭悔罪道歉請求重新返回師門繼續苦學，從此一輩子再也不敢輕易誇口言說回家的話了！秦青回頭對朋友們感慨說：當年著名歌唱家韓娥向東前往齊國，隨身攜帶的乾糧喫光了，路過齊國首都雍門之際，靠賣唱唱歌換取一口飯喫。韓娥唱完離去之後，她那優美動聽的歌聲餘音在房樑屋舍之間繚繞盤旋（餘音繞梁），整整三天三夜綿延不絕，周圍的街坊鄰裏還一直以為韓娥根本就未曾離開過呢！後來韓娥投宿一家客棧旅店，客棧老闆蠻橫無禮地羞辱侮辱了她。韓娥悲憤之下拖長聲音放聲哀聲痛哭，方圓一里之內的老老少少全被這撕心裂肺的哭聲所感染陷入了無盡的悲傷憂愁，所有人相對流淚痛哭流涕，整整三天喫不下飯！客棧老闆嚇得急忙一路狂追追上韓娥當面磕頭謝罪道歉，韓娥於是重新拖長聲音為大家放聲歡快長歌。一里之內的老老少少瞬間喜笑顏開歡呼跳躍拍手狂舞（喜躍抃舞），內心的歡喜情不自禁，完全忘卻了剛才經歷的滔天悲傷！大家於是備辦豐厚禮品熱情歡送韓娥啟程。所以齊國雍門一帶的百姓直到今天都特別擅長唱歌與悲哭，完全是在摹仿傳承韓娥當年遺留下來的神奇神韻啊！\",\"analysis\":\"【篇旨與薛譚學謳響遏行雲韓娥餘音繞梁藝術感染力巔峯】中國聲樂美學史上最燦爛奪目的雙壁傳奇——薛譚驕傲自滿被秦青「聲振林木響遏行雲」所折服，韓娥賣唱「餘音繞梁三日不絕、一哭老幼悲泣、一歌老幼抃舞」，確立藝術直擊靈魂的終極感染力。\\\\n【詞義訓詁】「響遏行雲」：歌聲嘹亮穿透雲霄，使行雲為之停駐；「餘音繞梁三日不絕」：聲音美感在空間與心靈中的長久迴響；「抃舞」：抃，音變，鼓掌拍手歡舞。\\\\n【美學境界】真正的藝術巨匠能以純粹的情感能量操控全場觀眾的心靈共振，超越單純的技巧炫耀而達到神妙化境。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-11\",\"chapterId\":\"liezi_ch-5\",\"order\":11,\"canonicalText\":\"造父以善御聞於天下，周穆王得驥、騮、騄、酈、驒、騂、驊、騮之駿，使造父御之，西巡狩，見西王母，樂而忘歸。徐偃王反，穆王日馳千里以救之，造父御車，不頓轡而至，遂平徐亂。造父學御於泰豆先生，始立三年，泰豆不言。造父益恭。泰豆乃告之曰：「古之言御者，非調馬也，調己也。得之於心，應之於手，身與車化，車與馬協，六轡在手，如撫琴絃。故不策而馬自馳，不引而車自正。此御之至也。」\",\"sentenceIds\":[\"liezi_ch-5_p-11_s-1\",\"liezi_ch-5_p-11_s-2\",\"liezi_ch-5_p-11_s-3\",\"liezi_ch-5_p-11_s-4\",\"liezi_ch-5_p-11_s-5\",\"liezi_ch-5_p-11_s-6\",\"liezi_ch-5_p-11_s-7\",\"liezi_ch-5_p-11_s-8\",\"liezi_ch-5_p-11_s-9\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"造父憑藉高超絕倫的駕車馭馬技術聞名於全天下，周穆王獲得了天下無雙的八匹絕世駿馬（赤驥、盜驪、白義、逾輪、山子、渠黃、華騮、綠耳），派遣造父專門為天子駕馭馬車，一路向西巡狩出巡，在崑崙山會見了西王母，沉醉在瑤池宴樂之中歡樂得忘記了班師回朝。這時東方的徐偃王發動叛亂謀反，周穆王緊急命令以一日千里之速日夜狂馳馳援平叛；造父親自為穆王駕車，一路狂馳連馬韁繩都未曾停歇頓挫一下就風馳電掣般及時趕回中原，迅速平定了徐偃王的叛亂。造父當年跟隨泰豆先生學習馭車之術時，剛入門站立侍奉了整整三年，泰豆先生一句話也沒教給他。造父的態度反而更加謙恭謹慎。泰豆先生這才親自指點傳授他說：古代真正懂得駕馭之術的至人，從來不是單純去強行調教馴服馬匹，而是首先調養調和自己的內在身心（調己）！心中領悟了大道的節奏分寸，雙手精準神妙響應操控，身軀形體與奔馳的車輿融為一體，車輿的重心與駿馬的步伐高度協同；六根韁繩握在雙手之中，就如同撫弄優美的古琴琴絃一樣輕柔靈敏！所以不需要揮動皮鞭抽打而駿馬自然飛馳狂奔，不需要用力拉扯韁繩而車輪自然端正平直！這正是駕馭馭馬之術所能達到的最高至境啊！\",\"analysis\":\"【篇旨與造父學御調馬不如調己身車馬三位一體駕馭哲學】古代交通與駕駛技術最高哲學總結——泰豆傳授造父「非調馬也調己也、得心應手、身與車化車與馬協」，以撫琴比喻控韁，揭示人機合一、調和自我的最高控制論。\\\\n【詞義訓詁】「造父御車平徐亂」：歷史上著名的駕車狂馳平叛功勳；「調馬不如調己」：管理外在對象前必先管理自我情緒與身心狀態；「六轡在手如撫琴絃」：極致細膩靈敏的反饋調節機制。\\\\n【現代控制理論與管理學】卓越的系統控制與領導管理，核心不在於施加暴力外部強制，而在於駕駛者自身心態的沉穩與對系統反饋的精準協同。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-12\",\"chapterId\":\"liezi_ch-5\",\"order\":12,\"canonicalText\":\"魏黑卵以善力聞，私怨丘丙。丘丙之子來丹，謀復父仇。來丹求得衛孔周之三寶劍：一曰含光，二曰承影，三曰宵練。含光者，視不可見，運之不知其所觸，泯然無際；承影者，將旦昧爽之交，日夕昏明之際，北面而察之，淡淡焉若有物存，莫知其狀；宵練者，晝見其影，不見其光，夜見其光，不見其形。來丹操承影以擊黑卵，引刃而過，黑卵不知也。來丹以為死，引去。黑卵起，拊頸曰：「曏者若有物刺我，吾頸何微痛也？」列子聞之曰：「至剛者無剛，至柔者無柔。含光、承影、宵練，器之微者也，故能入無間而行無形。」\",\"sentenceIds\":[\"liezi_ch-5_p-12_s-1\",\"liezi_ch-5_p-12_s-2\",\"liezi_ch-5_p-12_s-3\",\"liezi_ch-5_p-12_s-4\",\"liezi_ch-5_p-12_s-5\",\"liezi_ch-5_p-12_s-6\",\"liezi_ch-5_p-12_s-7\",\"liezi_ch-5_p-12_s-8\",\"liezi_ch-5_p-12_s-9\",\"liezi_ch-5_p-12_s-10\",\"liezi_ch-5_p-12_s-11\",\"liezi_ch-5_p-12_s-12\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魏國勇士黑卵憑藉一身兇悍神力聞名於世，他曾因私仇殺害了丘丙。丘丙的兒子來丹發誓要為父親報仇雪恨。來丹四處尋訪，終於從衛國貴族孔周那裡求得了傳世的三把上古神劍：第一把神劍名叫含光，第二把神劍名叫承影，第三把神劍名叫宵練。含光劍的特點是：用肉眼看根本看不見它的劍身形體，揮舞運轉它也絲毫感覺不到它劈砍觸及了什麼物體，劍鋒與虛空渾然一體毫無痕跡邊際；承影劍的特點是：在清晨黑夜即將破曉微明交替的黎明之際，或傍晚黃昏即將入夜昏明交替之時，面向北面迎著微光仔細觀察，隱隱約約淡淡然彷彿有某種物體存在，卻始終無法看清它的具體形貌形狀；宵練劍的特點是：在白天只能看見它的淡淡劍影而看不見它的鋒利光芒，在夜晚只能看見它的雪亮光芒而看不見它的劍體形態。來丹手持承影神劍潛入黑卵家中向黑卵發動攻擊，揮動神劍利刃從黑卵的脖頸上一掠而過，黑卵竟然毫無察覺依舊熟睡。來丹以為黑卵必死無疑，便抽身退去了。過了一會兒黑卵翻身起牀，摸著自己的脖子疑惑地說：剛纔好像有什麼微風細草刺了我的脖子一下，我的脖子怎麼有一點點隱隱作痛呢？列子聽聞這件事後感慨說：至高無上的剛強超越了一切顯露的剛硬外表，至高無上的陰柔超越了一切死板的柔軟形態。含光、承影、宵練三把神劍，乃是世間將物質提煉到了極致精微虛無的神器啊，所以它能夠如老子所言無厚入有間，穿行於虛無之中而斬物於無形無相啊！\",\"analysis\":\"【篇旨與孔週三劍含光承影宵練無厚入有間極限物質科幻】先秦兵器與物理哲學最神奇的科幻名篇——描繪「含光（無形無觸）、承影（光影交界微現）、宵練（晝影夜光）」三把光子/等離子態神劍，列子提煉出「至剛無剛、至柔無柔、入無間行無形」之極致哲理。\\\\n【詞義訓詁】「含光／承影／宵練」：中國古典神劍文化三大傳奇圖騰；「昧爽」：黎明破曉時分；「入無間」：語出《老子》第四十三章「無有入無間」，以虛無之至微穿透物質之縫隙。\\\\n【物理學與美學想像】先秦哲人以超前的想像力構想出擺脫常規固態宏觀質量的微觀能量態利刃，展現出極具東方神祕色彩的微觀物理哲學。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-13\",\"chapterId\":\"liezi_ch-5\",\"order\":13,\"canonicalText\":\"齊景公遊於牛山，北臨其國城而流涕曰：「美哉國乎！鬱鬱蔥蔥，若何滴滴去此而死乎？使古無死者，寡人將去斯而何之？」晏子曰：「善哉！湯武之不存，乃有景公之位。若使古無死者，古之先君常在，則桓、文當之矣，君何得而居之？君之得有此國，因古之有死也。何為而泣？」景公慚焉。\",\"sentenceIds\":[\"liezi_ch-5_p-13_s-1\",\"liezi_ch-5_p-13_s-2\",\"liezi_ch-5_p-13_s-3\",\"liezi_ch-5_p-13_s-4\",\"liezi_ch-5_p-13_s-5\",\"liezi_ch-5_p-13_s-6\",\"liezi_ch-5_p-13_s-7\",\"liezi_ch-5_p-13_s-8\",\"liezi_ch-5_p-13_s-9\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"齊景公前往牛山郊遊登高，站在山頂面向北面俯瞰齊國繁華雄偉的國都臨淄城，忍不住傷心落淚痛哭流涕道：多麼壯麗美好的錦繡江山啊！草木繁茂鬱鬱蔥蔥，為什麼我們人類偏偏要像雨滴滴落一樣無可奈何地離開這美好的世界而死去呢？如果自古以來人類從來就不會死亡的話，寡人又將去往哪裡享受更加美好的生活呢？大臣晏子走上前坦率進諫說：太好了！正是因為古代的商湯、周武王等聖王先祖不會長生不死，今天才輪得到您齊景公坐上國君的大位啊！假使自古以來人類真的從來都不會死亡，古代的開國先君始終霸佔著王位，隨後齊桓公、晉文公等雄主也永遠活在世上執政，那麼君王您今天又怎麼可能登上王位君臨天下呢？君王您今天之所以能擁有這齊國的江山社稷，全都是因為自古以來人人都有死亡這一客觀規律所賜予您的恩德啊！您現在又有什麼好為此傷心痛哭的呢？齊景公聽後羞愧難當無地自容。\",\"analysis\":\"【篇旨與齊景公牛山流涕晏子論死生更替歷史進步論】記錄齊景公牛山嘆老惜死，晏子以「古若無死君何得居位」當頭棒喝，深刻揭示代際死亡與新陳代謝乃推動歷史演進與社會流動的必然規律。\\\\n【詞義訓詁】「鬱鬱蔥蔥」：臨淄繁華景象；「滴滴去此而死」：感嘆生命短暫如水滴消逝；「因古之有死」：死亡促進代際交替、打破特權階層永恆壟斷。\\\\n【歷史哲學啟示】破除統治者妄圖長生不老、永恆霸佔權力的反動妄念，確立生老病死自然代謝對人類社會公平與活力的積極保障作用。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-14\",\"chapterId\":\"liezi_ch-5\",\"order\":14,\"canonicalText\":\"楚人有養狙以為生者，楚人謂之狙公。旦暮賦芧，曰：「朝三而暮四。」眾狙皆怒。俄而曰：「然則朝四而暮三。」眾狙皆喜。物之以名實相差，亦由是也。聖人以智籠天下，民不知其術，皆自以為得也。\",\"sentenceIds\":[\"liezi_ch-5_p-14_s-1\",\"liezi_ch-5_p-14_s-2\",\"liezi_ch-5_p-14_s-3\",\"liezi_ch-5_p-14_s-4\",\"liezi_ch-5_p-14_s-5\",\"liezi_ch-5_p-14_s-6\",\"liezi_ch-5_p-14_s-7\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"楚國有一個靠飼養獼猴羣謀生的人，楚國人都稱呼他為狙公。每天早晨和傍晚給猴羣分發橡樹果實（芧）時，狙公對猴子們說：早晨給你們喫三升，晚上給你們喫四升。羣猴聽了都憤怒咆哮大發脾氣。過了一會兒狙公改口說：既然這樣，那就早晨給你們喫四升，晚上給你們喫三升吧！羣猴聽了全都興高采烈喜笑顏開。世間萬事萬物因為名稱概念（名）與客觀實質（實）的表象差異而讓人產生心理幻覺，全都是如同朝三暮四這般道理啊！聖王明哲善於運用高明的心理智謀籠絡統轄天下，百姓在不知不覺中順應了體制秩序，卻全都自以為自己爭取到了最滿意的利益呢！\",\"analysis\":\"【篇旨與朝三暮四名實之辨心理學話術與制度設計】先秦名實哲學與行為經濟學最經典寓言——總量七升不變，僅通過調整時序（朝三暮四 vs 朝四暮三）便徹底逆轉猴羣情緒（怒轉喜），揭示人類普遍存在的「框架效應（Framing Effect）」與短期偏好偏誤。\\\\n【詞義訓詁】「狙公」：狙，音居，獼猴；「芧」：芧，音序，橡子橡樹果；「名實相差」：實質等同而表述框架不同引發認知偏差；「以智籠天下」：公共政策之引導與心理調控藝術。\\\\n【行為經濟學價值】精闢洞悉人類「損失厭惡」與「當下偏好」心理，成為現代公共政策溝通、定價策略與談判管理的核心案例。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-15\",\"chapterId\":\"liezi_ch-5\",\"order\":15,\"canonicalText\":\"周宣王之時，有尹鐸者，善問。問於老聃曰：「請問長生之道。」老聃曰：「生生者不生，化化者不化。夫唯不生，故能生生；夫唯不化，故能化化。天長地久，以其不自生，故能長生。人能虛心實腹，挫銳解紛，與道同體，則雖死而不亡，此長生之真諦也。」\",\"sentenceIds\":[\"liezi_ch-5_p-15_s-1\",\"liezi_ch-5_p-15_s-2\",\"liezi_ch-5_p-15_s-3\",\"liezi_ch-5_p-15_s-4\",\"liezi_ch-5_p-15_s-5\",\"liezi_ch-5_p-15_s-6\",\"liezi_ch-5_p-15_s-7\",\"liezi_ch-5_p-15_s-8\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"周宣王在位之時，有一位名叫尹鐸的學者，非常善於發問求道。他向老子請教道：請問世間真正的長生久視之道究竟是什麼呢？老子回答說：賦予萬物生命的生化本體自身超越生死，推動萬物轉化的演化本體自身不受轉化。正因為大道本體不入生死輪迴，所以才能持續生化億萬萬物；正因為大道本體不受物質轉化局限，所以才能持續轉化世間一切造化。天地之所以能夠長久永恆長存，是因為天地生養萬物卻從不為自己私自謀求生存，所以才能實現真正的永恆長生。人如果能夠做到放空私心成見、充實內在元氣（虛心實腹），磨挫自身鋒芒、解脫人世紛擾（挫銳解紛），使自身的精神品格與永恆大道融為同一本體，那麼縱然肉身壽終正寢而精神思想永垂不朽（死而不亡者壽），這才是長生久視的最高真諦啊！\",\"analysis\":\"【篇旨與老聃答尹鐸虛心實腹死而不亡長生真諦】重申老子核心教義——引用《道德經》第七章（天長地久不自生）、第十二章（虛心實腹）、第三十三章（死而不亡者壽），將道家追求之「長生」從肉身不死迷信昇華為精神與大道同體的永恆不朽。\\\\n【詞義訓詁】「生生者不生」：生化萬物之本體超越個體生滅；「挫銳解紛」：消除主觀鋒芒與紛擾執念；「死而不亡者壽」：精神與文化遺產萬代長存。\\\\n【生死哲學昇華】徹底摒棄外丹服藥與肉體永生妄念，確立通過精神修養、思想創造與造福社會實現生命真正永恆的崇高境界。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-16\",\"chapterId\":\"liezi_ch-5\",\"order\":16,\"canonicalText\":\"共工氏與顓頊爭為帝，怒而觸不周之山，折天柱，絕地維。天傾西北，故日月星辰移焉；地不滿東南，故水潦塵埃歸焉。聖人因天地之變，立綱陳紀，修補人倫，使天下復安。故曰：天道無常，因變以成。\",\"sentenceIds\":[\"liezi_ch-5_p-16_s-1\",\"liezi_ch-5_p-16_s-2\",\"liezi_ch-5_p-16_s-3\",\"liezi_ch-5_p-16_s-4\",\"liezi_ch-5_p-16_s-5\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"上古部族首領共工氏與顓頊帝爭奪天下天子帝位，兵敗之後憤怒到了極點，一頭猛烈撞擊了西北方支撐天地的天柱——不周山！結果直接撞折了擎天巨柱，撞斷了拴繫大地的四方繩索（絕地維）。蒼天朝著西北方向劇烈傾斜，所以天上的太陽、月亮與漫天星辰都向西北方偏斜運轉；大地朝著東南方向劇烈塌陷不滿，所以天下所有的江河流水、泥沙塵埃全都奔騰匯聚歸向東南方大海！古代聖王順應天地大自然的劇烈巨變，重新確立法律綱領陳設社會紀律，修復彌補受損的人倫道德秩序，使全天下重新恢復了和平安寧。所以古人說：天道自然運轉從來沒有僵化不變的死板常態，唯有因時制宜順應劇烈變革才能成就偉大功業！\",\"analysis\":\"【篇旨與共工怒觸不周山天地傾斜因變以成神話地理學】中國最宏偉的上古神話創世史詩——共工觸不周山致「天傾西北、地陷東南」，科學解釋中國地理西北高東南低、江河東流之宏觀地貌成因，並推導出「天道無常、因變以成」的社會變革哲學。\\\\n【詞義訓詁】「不周之山」：神話中支撐西北天穹之天柱；「天傾西北／地不滿東南」：中國大陸第一、二、三級階梯地形與河流走向的神話學表述；「因變以成」：在危機與劇變中重構秩序。\\\\n【科學與哲學價值】巧妙融通了自然地理大格局的宏觀觀察與應對歷史危機的改革變法思維。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-5_p-17\",\"chapterId\":\"liezi_ch-5\",\"order\":17,\"canonicalText\":\"湯問篇終。子列子曰：「天地之大，萬物之怪，非耳目所能盡察，非心智所能盡窮。夏革之對，發宇宙之微；愚公之志，動天地之感；伯牙之琴，通心靈之趣；偃師之巧，侔造化之功。皆道之發越也。知夫道包天地，貫古今，通萬物，則天下無奇異矣。」\",\"sentenceIds\":[\"liezi_ch-5_p-17_s-1\",\"liezi_ch-5_p-17_s-2\",\"liezi_ch-5_p-17_s-3\",\"liezi_ch-5_p-17_s-4\",\"liezi_ch-5_p-17_s-5\",\"liezi_ch-5_p-17_s-6\",\"liezi_ch-5_p-17_s-7\",\"liezi_ch-5_p-17_s-8\",\"liezi_ch-5_p-17_s-9\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"〈湯問〉篇總結。列子說：宇宙天地的浩瀚廣大，世間萬物的千奇百怪，絕非人類肉體耳目所能完全觀察窮盡，絕非世俗有限心智所能完全推演窮極。夏革對商湯的精妙問答，揭示了宇宙時空無極無窮的微言大義；北山愚公的移山壯志，激發了撼動天地神靈的真誠感應；俞伯牙撫弄的高山流水古琴，融會貫通了心靈知音的最高妙趣；偃師發明的人造歌舞機器人，達到了比肩天地造化的神奇神工！這一切令人震撼的奇蹟，全都是真理大道在不同領域的浩蕩顯發與展現啊！如果能深刻懂得大道包容宇宙天地、貫通古今歷史、融通世間萬物的至高原理，那麼全天下就再也沒有什麼值得少見多怪的奇異之處了！\",\"analysis\":\"【篇旨與湯問全篇終結大道包貫無奇不有宇宙總綱】〈湯問〉終篇總結——系統串聯夏革時空論、愚公移山、伯牙絕絃、偃師造倡等經典篇章，總括為「皆道之發越、道包天地貫古今」，確立開放包容、探索未知的科學探索與哲學情懷。\\\\n【詞義訓詁】「侔造化之功」：侔，音謀，等同、比肩；人類科技創造力比肩大自然神工；「天下無奇異」：在至高大道視角下，一切看似不可思議之奇蹟皆有其深刻的底層客觀規律。\\\\n【全篇哲學昇華】將神話、科技、美學、地質與哲學完美熔鑄於道體之中，展現了先秦文明最浪漫壯闊的宇宙情懷。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"liezi_ch-5_p-1_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":1,\"canonicalText\":\"殷湯問於夏革曰：「古初有物乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":2,\"canonicalText\":\"」夏革曰：「古初無物，今惡得物？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":3,\"canonicalText\":\"後之人將謂今之無物，可乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":4,\"canonicalText\":\"」殷湯曰：「然則物無先後乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":5,\"canonicalText\":\"」夏革曰：「物之始終，初無極已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":6,\"canonicalText\":\"始或為終，終或為始，惡知其紀？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":7,\"canonicalText\":\"若夫物外之物，事外之事，吾所不識也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":8,\"canonicalText\":\"」殷湯曰：「上下八方有極盡窮乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":9,\"canonicalText\":\"」革曰：「不知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":10,\"canonicalText\":\"」湯固問。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":11,\"canonicalText\":\"革曰：「無則無極，有則有盡，吾何以知之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":12,\"canonicalText\":\"然無極之外，復無極也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":13,\"canonicalText\":\"無窮之中，復無窮也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":14,\"canonicalText\":\"朕以是知其無極無窮也，而不知其有極有窮也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-1_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-1\",\"order\":15,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-2_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-2\",\"order\":1,\"canonicalText\":\"湯又問曰：「四海之外奚有？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-2_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-2\",\"order\":2,\"canonicalText\":\"」革曰：「猶齊州也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-2_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-2\",\"order\":3,\"canonicalText\":\"」湯曰：「奚以知之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-2_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-2\",\"order\":4,\"canonicalText\":\"」革曰：「朕南中九疑，北抵幽陵，東逾扶桑，西至弱水。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-2_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-2\",\"order\":5,\"canonicalText\":\"見其凡物，無以異於齊州者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-2_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-2\",\"order\":6,\"canonicalText\":\"是故以大觀小，以小觀大，知其皆齊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-2_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-2\",\"order\":7,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":1,\"canonicalText\":\"太行、王屋二山，方七百里，高萬仞，本在冀州之南，河陽之北。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":2,\"canonicalText\":\"北山愚公者，年且九十，面山而居。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":3,\"canonicalText\":\"懲山北之塞，出入之迂也，聚室而謀曰：「吾與汝畢力平險，指通豫南，達於漢陰，可乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":4,\"canonicalText\":\"」雜然相許。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":5,\"canonicalText\":\"其妻獻疑曰：「以君之力，曾不能損魁父之丘，如太行、王屋何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":6,\"canonicalText\":\"且焉置土石？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":7,\"canonicalText\":\"」雜曰：「投諸渤海之尾，隱土之北。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":8,\"canonicalText\":\"」遂率子孫荷擔者三夫，叩石墾壤，箕畚運於渤海之尾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":9,\"canonicalText\":\"鄰人京城氏之孀妻有遺男，始齔，跳往助之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":10,\"canonicalText\":\"寒暑易節，始一反焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":11,\"canonicalText\":\"河曲智叟笑而止之曰：「甚矣，汝之不惠！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":12,\"canonicalText\":\"以殘年餘力，曾不能毀山之一毛，其如土石何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":13,\"canonicalText\":\"」北山愚公長息曰：「汝心之固，固不可徹，曾不若孀妻弱子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":14,\"canonicalText\":\"雖我之死，有子存焉；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":15,\"canonicalText\":\"子又生孫，孫又生子；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":16,\"canonicalText\":\"子又有子，子又有孫；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":17,\"canonicalText\":\"子子孫孫無窮匱也，而山不加增，何苦而不平？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":18,\"canonicalText\":\"」河曲智叟亡以應。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":19,\"canonicalText\":\"操蛇之神聞之，懼其不已也，告之於帝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":20,\"canonicalText\":\"帝感其誠，命誇娥氏二子負二山，一厝朔東，一厝雍南。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-3_s-21\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-3\",\"order\":21,\"canonicalText\":\"自此，冀之南，漢之陰，無隴斷焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-4_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-4\",\"order\":1,\"canonicalText\":\"夸父不量力，欲追日影，逐之於隅谷之際。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-4_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-4\",\"order\":2,\"canonicalText\":\"渴欲得飲，赴飲河、渭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-4_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-4\",\"order\":3,\"canonicalText\":\"河、渭不足，將走北飲大澤。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-4_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-4\",\"order\":4,\"canonicalText\":\"未至，道渴而死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-4_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-4\",\"order\":5,\"canonicalText\":\"棄其杖，屍膏肉所浸，生鄧林。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-4_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-4\",\"order\":6,\"canonicalText\":\"鄧林彌廣數千里焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":1,\"canonicalText\":\"伯牙善鼓琴，鍾子期善聽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":2,\"canonicalText\":\"伯牙鼓琴，志在高山。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":3,\"canonicalText\":\"鍾子期曰：「善哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":4,\"canonicalText\":\"峨峨兮若泰山！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":5,\"canonicalText\":\"」志在流水。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":6,\"canonicalText\":\"鍾子期曰：「善哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":7,\"canonicalText\":\"洋洋兮若江河！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":8,\"canonicalText\":\"」伯牙所念，鍾子期必得之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":9,\"canonicalText\":\"伯牙遊於泰山之陰，卒逢暴雨，止於巖下；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":10,\"canonicalText\":\"心悲，乃援琴而鼓之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":11,\"canonicalText\":\"初為霖雨之操，更造崩山之音。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":12,\"canonicalText\":\"曲每奏，鍾子期輒窮其趣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":13,\"canonicalText\":\"伯牙乃舍琴而歎曰：「善哉，善哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":14,\"canonicalText\":\"子之聽夫！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":15,\"canonicalText\":\"志想像猶吾心也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":16,\"canonicalText\":\"吾於何逃聲哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-5_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-5\",\"order\":17,\"canonicalText\":\"」子期死，伯牙謂世再無知音，乃破琴絕絃，終身不復鼓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-6_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-6\",\"order\":1,\"canonicalText\":\"孔子東遊，見兩小兒辯鬥，問其故。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-6_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-6\",\"order\":2,\"canonicalText\":\"一兒曰：「我以日始出時去人近，而日中時遠也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-6_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-6\",\"order\":3,\"canonicalText\":\"」一兒以日初出遠，而日中時近也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-6_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-6\",\"order\":4,\"canonicalText\":\"一兒曰：「日初出大如車蓋，及日中則如盤盂，此不為遠者小而近者大乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-6_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-6\",\"order\":5,\"canonicalText\":\"」一兒曰：「日初出滄滄涼涼，及其日中如探湯，此不為近者熱而遠者涼乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-6_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-6\",\"order\":6,\"canonicalText\":\"」孔子不能決也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-6_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-6\",\"order\":7,\"canonicalText\":\"兩小兒笑曰：「孰為汝多知乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-6_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-6\",\"order\":8,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":1,\"canonicalText\":\"周穆王西巡狩，越昆侖，不至弇山，反還。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":2,\"canonicalText\":\"中道，塗之人有以巧工謁者，名曰偃師。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":3,\"canonicalText\":\"穆王薦之，問曰：「若何能？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":4,\"canonicalText\":\"」偃師曰：「臣唯命所試。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":5,\"canonicalText\":\"然臣已造一物，願王先觀之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":6,\"canonicalText\":\"」穆王曰：「日以俱來。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":7,\"canonicalText\":\"」明日，偃師謁見王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":8,\"canonicalText\":\"王疾迎之曰：「若與偕來者何人邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":9,\"canonicalText\":\"」對曰：「臣之所造能倡者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":10,\"canonicalText\":\"」穆王驚視之，趣步俯仰，信人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":11,\"canonicalText\":\"巧夫！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":12,\"canonicalText\":\"頞其頤，則歌合律；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":13,\"canonicalText\":\"捧其手，則舞應節。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":14,\"canonicalText\":\"千變萬化，惟意所適。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":15,\"canonicalText\":\"王以為實人也，與盛姬內御並觀之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":16,\"canonicalText\":\"技將畢，倡者瞬目而招王之左右侍妾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":17,\"canonicalText\":\"王大怒，立欲誅偃師。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":18,\"canonicalText\":\"偃師大恐，立剖散倡者以示王，皆傅會革、木、膠、漆、白、黑、丹、青之所為。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":19,\"canonicalText\":\"王諦料之，內則肝、膽、心、肺、脾、腎、腸、胃，外則筋、骨、支、節、皮、毛、齒、髮，皆假物也，而無不畢具者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":20,\"canonicalText\":\"合之復如初見。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-21\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":21,\"canonicalText\":\"王試廢其心，則口不能言；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-22\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":22,\"canonicalText\":\"廢其肝，則目不能視；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-23\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":23,\"canonicalText\":\"廢其腎，則足不能步。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-24\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":24,\"canonicalText\":\"穆王始悅而歎曰：「人之巧，乃可與造化者同功乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-7_s-25\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-7\",\"order\":25,\"canonicalText\":\"」詔貳車載之以歸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":1,\"canonicalText\":\"魯公扈、趙齊嬰二人有疾，同請扁鵲求治。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":2,\"canonicalText\":\"扁鵲治之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":3,\"canonicalText\":\"既同愈。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":4,\"canonicalText\":\"謂公扈、齊嬰曰：「汝曩之所疾，自外而入者，故藥石之所已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":5,\"canonicalText\":\"今有疾，並生於齊，與生偕長，予為汝攻之，何如？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":6,\"canonicalText\":\"」二人曰：「願聞其狀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":7,\"canonicalText\":\"」扁鵲謂公扈曰：「汝志強而氣弱，故足於謀而寡於斷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":8,\"canonicalText\":\"齊嬰志弱而氣強，故少於慮而喪於勇。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":9,\"canonicalText\":\"若換汝之心，則均於善矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":10,\"canonicalText\":\"」扁鵲遂飲二人毒酒，迷死三日，剖胸探心，易而置之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":11,\"canonicalText\":\"投以神藥，既悟如初。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":12,\"canonicalText\":\"二人辭歸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":13,\"canonicalText\":\"於是公扈反齊嬰之室，賂其妻子，妻子弗識。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":14,\"canonicalText\":\"齊嬰反公扈之室，室人亦弗識。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":15,\"canonicalText\":\"二室訟，求審於扁鵲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-8_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-8\",\"order\":16,\"canonicalText\":\"扁鵲辨其所由，訟乃息。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":1,\"canonicalText\":\"甘蠅，古之善射者，彀弓而獸伏鳥下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":2,\"canonicalText\":\"弟子名飛衛，學射於甘蠅，而巧過其師。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":3,\"canonicalText\":\"紀昌者，又學射於飛衛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":4,\"canonicalText\":\"飛衛曰：「爾先學不瞬，而後可言射矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":5,\"canonicalText\":\"」紀昌歸，偃臥其妻之機下，以目承牽挺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":6,\"canonicalText\":\"二年之後，雖錐末倒眥，而不瞬也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":7,\"canonicalText\":\"以告飛衛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":8,\"canonicalText\":\"飛衛曰：「未也，必學視而後可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":9,\"canonicalText\":\"視小如大，視微如著，而後告我。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":10,\"canonicalText\":\"」昌以旄牛尾之毛懸蝨於牖，南面而望之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":11,\"canonicalText\":\"旬日之間，浸大也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":12,\"canonicalText\":\"三年之後，如車輪焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":13,\"canonicalText\":\"以睹餘物，皆丘山也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":14,\"canonicalText\":\"乃以燕角之弧、朔蓬之簳射之，貫蝨之心，而懸不絕。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":15,\"canonicalText\":\"以告飛衛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":16,\"canonicalText\":\"飛衛高蹈拊膺曰：「汝得之矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":17,\"canonicalText\":\"」紀昌既盡衛之術，計天下之敵己者，一人而已，乃謀殺飛衛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":18,\"canonicalText\":\"相遇於野，二人交射；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":19,\"canonicalText\":\"中路，矢鋒相觸，墜於地，而塵不揚。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":20,\"canonicalText\":\"飛衛之矢先窮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-21\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":21,\"canonicalText\":\"紀昌遺一矢，既發，飛衛以棘刺之端扞之，而無差焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-9_s-22\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-9\",\"order\":22,\"canonicalText\":\"於是二子泣而投弓，相與拜於塗，請為父子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":1,\"canonicalText\":\"薛譚學謳於秦青，未窮青之術，自謂盡之，遂辭歸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":2,\"canonicalText\":\"秦青弗止，餞於郊衢，撫節悲歌，聲振林木，響遏行雲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":3,\"canonicalText\":\"薛譚乃謝求反，終身不敢言歸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":4,\"canonicalText\":\"秦青顧謂其友曰：「昔韓娥東之齊，匱糧，過雍門，鬻歌假食。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":5,\"canonicalText\":\"既去，而餘音繞梁，三日不絕，左右以其人弗去。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":6,\"canonicalText\":\"過逆旅，逆旅人辱之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":7,\"canonicalText\":\"韓娥因曼聲哀哭，一里老幼悲愁，垂涕相對，三日不食。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":8,\"canonicalText\":\"急追而謝之，娥復為曼聲長歌。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":9,\"canonicalText\":\"一里老幼喜躍抃舞，弗能自禁，忘向之悲也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":10,\"canonicalText\":\"乃厚賂發之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":11,\"canonicalText\":\"故雍門之人至今善歌哭，放娥之遺聲也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-10_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-10\",\"order\":12,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-11_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-11\",\"order\":1,\"canonicalText\":\"造父以善御聞於天下，周穆王得驥、騮、騄、酈、驒、騂、驊、騮之駿，使造父御之，西巡狩，見西王母，樂而忘歸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-11_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-11\",\"order\":2,\"canonicalText\":\"徐偃王反，穆王日馳千里以救之，造父御車，不頓轡而至，遂平徐亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-11_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-11\",\"order\":3,\"canonicalText\":\"造父學御於泰豆先生，始立三年，泰豆不言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-11_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-11\",\"order\":4,\"canonicalText\":\"造父益恭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-11_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-11\",\"order\":5,\"canonicalText\":\"泰豆乃告之曰：「古之言御者，非調馬也，調己也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-11_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-11\",\"order\":6,\"canonicalText\":\"得之於心，應之於手，身與車化，車與馬協，六轡在手，如撫琴絃。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-11_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-11\",\"order\":7,\"canonicalText\":\"故不策而馬自馳，不引而車自正。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-11_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-11\",\"order\":8,\"canonicalText\":\"此御之至也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-11_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-11\",\"order\":9,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":1,\"canonicalText\":\"魏黑卵以善力聞，私怨丘丙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":2,\"canonicalText\":\"丘丙之子來丹，謀復父仇。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":3,\"canonicalText\":\"來丹求得衛孔周之三寶劍：一曰含光，二曰承影，三曰宵練。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":4,\"canonicalText\":\"含光者，視不可見，運之不知其所觸，泯然無際；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":5,\"canonicalText\":\"承影者，將旦昧爽之交，日夕昏明之際，北面而察之，淡淡焉若有物存，莫知其狀；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":6,\"canonicalText\":\"宵練者，晝見其影，不見其光，夜見其光，不見其形。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":7,\"canonicalText\":\"來丹操承影以擊黑卵，引刃而過，黑卵不知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":8,\"canonicalText\":\"來丹以為死，引去。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":9,\"canonicalText\":\"黑卵起，拊頸曰：「曏者若有物刺我，吾頸何微痛也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":10,\"canonicalText\":\"」列子聞之曰：「至剛者無剛，至柔者無柔。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":11,\"canonicalText\":\"含光、承影、宵練，器之微者也，故能入無間而行無形。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-12_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-12\",\"order\":12,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-13_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-13\",\"order\":1,\"canonicalText\":\"齊景公遊於牛山，北臨其國城而流涕曰：「美哉國乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-13_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-13\",\"order\":2,\"canonicalText\":\"鬱鬱蔥蔥，若何滴滴去此而死乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-13_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-13\",\"order\":3,\"canonicalText\":\"使古無死者，寡人將去斯而何之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-13_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-13\",\"order\":4,\"canonicalText\":\"」晏子曰：「善哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-13_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-13\",\"order\":5,\"canonicalText\":\"湯武之不存，乃有景公之位。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-13_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-13\",\"order\":6,\"canonicalText\":\"若使古無死者，古之先君常在，則桓、文當之矣，君何得而居之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-13_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-13\",\"order\":7,\"canonicalText\":\"君之得有此國，因古之有死也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-13_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-13\",\"order\":8,\"canonicalText\":\"何為而泣？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-13_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-13\",\"order\":9,\"canonicalText\":\"」景公慚焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-14_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-14\",\"order\":1,\"canonicalText\":\"楚人有養狙以為生者，楚人謂之狙公。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-14_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-14\",\"order\":2,\"canonicalText\":\"旦暮賦芧，曰：「朝三而暮四。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-14_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-14\",\"order\":3,\"canonicalText\":\"」眾狙皆怒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-14_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-14\",\"order\":4,\"canonicalText\":\"俄而曰：「然則朝四而暮三。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-14_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-14\",\"order\":5,\"canonicalText\":\"」眾狙皆喜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-14_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-14\",\"order\":6,\"canonicalText\":\"物之以名實相差，亦由是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-14_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-14\",\"order\":7,\"canonicalText\":\"聖人以智籠天下，民不知其術，皆自以為得也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-15_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-15\",\"order\":1,\"canonicalText\":\"周宣王之時，有尹鐸者，善問。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-15_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-15\",\"order\":2,\"canonicalText\":\"問於老聃曰：「請問長生之道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-15_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-15\",\"order\":3,\"canonicalText\":\"」老聃曰：「生生者不生，化化者不化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-15_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-15\",\"order\":4,\"canonicalText\":\"夫唯不生，故能生生；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-15_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-15\",\"order\":5,\"canonicalText\":\"夫唯不化，故能化化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-15_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-15\",\"order\":6,\"canonicalText\":\"天長地久，以其不自生，故能長生。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-15_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-15\",\"order\":7,\"canonicalText\":\"人能虛心實腹，挫銳解紛，與道同體，則雖死而不亡，此長生之真諦也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-15_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-15\",\"order\":8,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-16_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-16\",\"order\":1,\"canonicalText\":\"共工氏與顓頊爭為帝，怒而觸不周之山，折天柱，絕地維。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-16_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-16\",\"order\":2,\"canonicalText\":\"天傾西北，故日月星辰移焉；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-16_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-16\",\"order\":3,\"canonicalText\":\"地不滿東南，故水潦塵埃歸焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-16_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-16\",\"order\":4,\"canonicalText\":\"聖人因天地之變，立綱陳紀，修補人倫，使天下復安。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-16_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-16\",\"order\":5,\"canonicalText\":\"故曰：天道無常，因變以成。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-17_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-17\",\"order\":1,\"canonicalText\":\"湯問篇終。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-17_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-17\",\"order\":2,\"canonicalText\":\"子列子曰：「天地之大，萬物之怪，非耳目所能盡察，非心智所能盡窮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-17_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-17\",\"order\":3,\"canonicalText\":\"夏革之對，發宇宙之微；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-17_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-17\",\"order\":4,\"canonicalText\":\"愚公之志，動天地之感；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-17_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-17\",\"order\":5,\"canonicalText\":\"伯牙之琴，通心靈之趣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-17_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-17\",\"order\":6,\"canonicalText\":\"偃師之巧，侔造化之功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-17_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-17\",\"order\":7,\"canonicalText\":\"皆道之發越也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-17_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-17\",\"order\":8,\"canonicalText\":\"知夫道包天地，貫古今，通萬物，則天下無奇異矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-5_p-17_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-5\",\"passageId\":\"liezi_ch-5_p-17\",\"order\":9,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
